'use strict';
const $=s=>document.querySelector(s),app=$('#app');let user=null,lessons=[],dashboard=null,admin=null,tab='lessons',active=null,step=null,selected=null,examBusy=false,lastViolation=0,clockOffset=0,timer=null,guarding=false,anal=null;let apiQueue=Promise.resolve(),studentRender=0,adminRender=0,statsRender=0,dashboardClockOffset=0;
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const date=v=>v?new Intl.DateTimeFormat('vi-VN',{timeZone:'Asia/Ho_Chi_Minh',dateStyle:'short',timeStyle:'short'}).format(new Date(v))+' (UTC+7)':'—';
const duration=s=>s==null?'—':Math.floor(s/60)+'p '+s%60+'s';
const topicName={A:'Máy tính và xã hội tri thức',B:'Mạng máy tính và Internet',C:'Đạo đức, pháp luật và văn hóa trong môi trường số',D:'Giải quyết vấn đề với sự trợ giúp của máy tính',E:'Hướng nghiệp với Tin học',F:'Máy tính và xã hội tri thức · Kết nối thiết bị số',G:'Ứng dụng tin học · Phần mềm tạo trang web'};
const examCategory=e=>e.id.startsWith('thpt-')?'mocks':/^(midterm|final)-/.test(e.id)?'terms':e.kind;
const examNotice=e=>examCategory(e)==='terms'?'Phạm vi học kỳ là khuyến nghị hoặc do giáo viên cấu hình; xem phạm vi bài và đối chiếu kế hoạch trường.':examCategory(e)==='mocks'?'Đề luyện theo dạng THPT: 24 trắc nghiệm + 4 đúng/sai. Thời gian thi chính thức 50 phút; chế độ luyện tại đây giữ 40 giây/câu hoặc ý, tối đa 26 phút 40 giây. Ma trận 40/30/30 là lựa chọn biên soạn, không phải tỉ lệ cố định đã xác minh của Bộ.':'';
function toast(text,error=false){const t=$('#toast');t.textContent=text;t.className=error?'error':'';t.hidden=false;clearTimeout(t._timeout);t._timeout=setTimeout(()=>t.hidden=true,6000)}
function api(action,data={}){const call=async()=>{const controller=new AbortController(),timeout=setTimeout(()=>controller.abort(),25000);let r;try{r=await fetch('/api',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({action,data}),signal:controller.signal});const x=await r.json();if(!r.ok){const e=Error(x.error||'Yêu cầu thất bại');e.status=r.status;if(r.status===401&&action!=='login'&&user)queueMicrotask(()=>{endExam();user=null;account();login();toast('Phiên đã hết hạn. Đăng nhập lại; đáp án đã gửi vẫn được giữ.',true)});throw e}if($('#exam-network'))$('#exam-network').textContent='';return x}catch(e){if(!e.status){const msg=active?'Không kết nối được máy chủ. Đồng hồ vẫn chạy; dùng Lấy lại câu hiện tại khi có mạng.':'Không kết nối được máy chủ. Kiểm tra mạng rồi thử tải lại; kiểm tra dữ liệu trước khi gửi lại thay đổi.';if($('#exam-network'))$('#exam-network').textContent=msg;throw Error(msg)}throw e}finally{clearTimeout(timeout)}};const promise=apiQueue.then(call,call);apiQueue=promise.catch(()=>{});return promise}
function account(){const a=$('#account');a.innerHTML=user?`<span>${esc(user.name)}</span><button class="ghost" id="logout">Đăng xuất</button>`:'<span class="tag">HỌC CHẮC · THI TỰ TIN</span>';if(user)$('#logout').onclick=async()=>{try{if(active&&!confirm('Đang làm bài. Nộp bài trước khi đăng xuất?'))return;if(active)await api('submit',{attemptId:active.id});endExam();await api('logout');user=null;account();login()}catch(e){toast(e.message,true)}}}
function login(){const isAdmin=location.pathname.startsWith('/admin');app.innerHTML=`<section class="start-layout"><div class="login-intro"><p class="eyebrow">KHÔNG GIAN HỌC TẬP · ICT 12</p><h1>Học từng bài.<br>Hiểu từng lỗi.<br><em>Vững từng chủ đề.</em></h1><p class="lead">Luyện tập có định hướng, kiểm tra đúng trọng tâm và biết chính xác phần kiến thức cần củng cố.</p><div class="facts"><div><strong>28</strong><span>bài học trong sách</span></div><div><strong>45</strong><span>bộ đề luyện tập</span></div><div><strong>40<span>s</span></strong><span>mỗi lượt suy nghĩ</span></div></div><p class="source">Theo SGK Tin học 12 – Kết nối tri thức, định hướng ICT. A–G tương ứng 7 chủ đề của sách, đủ Bài 1–28. Đề thi thử có thêm kiến thức tiền đề lớp 10–11; phân chia học kỳ là đề xuất.</p></div><form class="card login-form" id="login-form"><p class="eyebrow">${isAdmin?'DÀNH CHO GIÁO VIÊN':'TÀI KHOẢN DO GIÁO VIÊN CẤP'}</p><h2>${isAdmin?'Đăng nhập quản lý':'Chào bạn, bắt đầu nhé.'}</h2><div class="field"><label for="username">Tên đăng nhập</label><input id="username" name="username" autocomplete="username" required minlength="3" maxlength="50" placeholder="Ví dụ: lop12a01"></div><div class="field"><label for="password">Mật khẩu</label><input id="password" name="password" type="password" autocomplete="current-password" required maxlength="128" placeholder="Nhập mật khẩu được cấp"></div><button class="primary" type="submit">Đăng nhập <span>↗</span></button><p id="login-error" class="error" role="alert"></p><div class="rules"><strong>Riêng tư và minh bạch</strong><p>Không đăng kí công khai. Hệ thống lưu tên, lớp, câu trả lời, điểm, thời gian và sự kiện rời trang để giáo viên theo dõi việc học.</p><p>Chống gian lận trên trình duyệt chỉ giúp phát hiện và hạn chế; không thể ngăn chụp bằng thiết bị khác.</p></div></form></section>`;$('#login-form').onsubmit=async e=>{e.preventDefault();const b=e.target.querySelector('button');b.disabled=true;try{const x=await api('login',{username:$('#username').value,password:$('#password').value});user=x.user;account();await home()}catch(e){if($('#login-error'))$('#login-error').textContent=e.message;else toast(e.message,true);b.disabled=false}}}
async function home(){endExam();if(!user)return login();app.innerHTML='<p class="loading">Đang tải dữ liệu…</p>';try{if(user.role==='teacher'){PT.data=null;return renderPortal('overview')}if(user.role==='admin'){admin=await api('adminData');lessons=admin.lessons;tab='students';await renderAdmin()}else{dashboard=await api('dashboard');dashboardClockOffset=Date.now()-(dashboard.serverNow||Date.now());if(dashboard.user){user=dashboard.user;account()}lessons=dashboard.lessons;Object.assign(topicName,dashboard.curriculum?.topicLabels);await renderStudent()}}catch(e){if(user){app.innerHTML=`<section class="layout"><div class="empty"><h2>Chưa tải được dữ liệu</h2><p>${esc(e.message)}</p><button class="primary" id="retry-home">Thử tải lại</button></div></section>`;$('#retry-home').onclick=home}toast(e.message,true)}}
function header(title,sub){return`<div class="welcome"><div><p class="eyebrow">${user.role==='admin'?'KHÔNG GIAN GIÁO VIÊN':'KHÔNG GIAN CỦA '+esc(user.name.toUpperCase())}</p><h1>${title}</h1><p>${sub}</p></div><span class="pill">${user.role==='admin'?'Quản lý & đánh giá':esc(user.className||'Tin học 12 ICT')}</span></div>`}
function nav(items){return`<nav class="tabs" aria-label="Chức năng">${items.map(([id,name])=>`<button data-tab="${id}" class="${tab===id?'active':''}">${name}</button>`).join('')}</nav>`}
function bindTabs(render){document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=async()=>{tab=b.dataset.tab;try{await render()}catch(e){toast(e.message,true)}})}
function card(e){const attempts=dashboard.attempts.filter(a=>a.examId===e.id).length;const ongoing=dashboard.attempts.find(a=>a.status==='active');return`<article class="card exam-card ${e.open?'':'closed'}"><span class="topic-label">${({lesson:'LUYỆN THEO BÀI',topic:'KIỂM TRA CHỦ ĐỀ',combined:'ĐỀ KẾT HỢP',terms:e.mappingRecommended?'HỌC KỲ · GỢI Ý':'HỌC KỲ · KẾ HOẠCH GV',mocks:'THI THỬ THPT · CHẾ ĐỘ LUYỆN'})[examCategory(e)]} · ${e.topics.join(' + ')} · ${e.semester==='all'?'Cả năm':'HK '+esc(e.semester)}</span><h3>${esc(e.title)}</h3><p class="small">${e.mcq} câu trắc nghiệm · ${e.tf} câu đúng/sai<br>${e.scopeLessons&&examCategory(e)==='terms'?'Phạm vi: Bài '+esc(e.scopeLessons.join(', '))+' · HK '+esc(e.semester)+'<br>':''}Tối đa ${examCategory(e)==='mocks'?'26 phút 40 giây':e.minutes+' phút'} · Đã dùng ${attempts}/${e.attemptLimit} lượt</p><button class="primary" data-exam="${e.id}" ${!e.open||attempts>=e.attemptLimit||ongoing?'disabled':''}>${!e.open?'Đang đóng':attempts>=e.attemptLimit?'Hết lượt làm':'Bắt đầu làm bài'} <span>↗</span></button></article>`}
async function renderStudent(){const renderId=++studentRender;app.innerHTML=`<section class="layout">${header('Mỗi lần luyện, một bước tiến.','Đủ 28 bài học, 7 chủ đề và các đề ôn tập theo giai đoạn.')}${studentSummary()}${nav([['assignments','Bài được giao'],['progress','Tiến bộ & huy hiệu'],['leaderboard','Bảng xếp hạng'],['lessons','Theo bài học'],['topics','Theo chủ đề'],['combined','Đề kết hợp'],['terms','Giữa kỳ & cuối kỳ'],['mocks','Thi thử THPT'],['history','Lịch sử'],['analysis','Phân tích & ôn lại'],['help','Hướng dẫn'],['password','Mật khẩu']])}<div id="content"></div></section>`;bindTabs(renderStudent);const content=$('#content');if(tab==='help')return helpHTML(content);if(tab==='assignments')return assignmentsHTML(content);if(tab==='progress')return progressHTML(content,dashboard.progress,true);if(tab==='leaderboard')return leaderboardHTML(content);const ongoing=dashboard.attempts.find(a=>a.status==='active');if(['lessons','topics','combined','terms','mocks'].includes(tab)){let html=ongoing?`<div class="notice">Bạn có một bài chưa hoàn tất. Đồng hồ vẫn chạy khi rời trang. <button class="link" id="resume">Tiếp tục bài đang làm →</button></div>`:'';if(tab==='lessons'){for(const t of ['A','B','C','D','E','F','G'])html+=`<div class="section-head"><h2>Chủ đề ${t}</h2><p>${topicName[t]}</p></div><div class="grid">${dashboard.exams.filter(e=>e.kind==='lesson'&&e.topics.includes(t)).map(card).join('')}</div>`}else{const category=tab==='topics'?'topic':tab;const selectedExams=dashboard.exams.filter(e=>examCategory(e)===category);const notice=tab==='terms'?'Phạm vi đề: <strong>khuyến nghị hoặc do giáo viên cấu hình</strong>, không phải phân phối học kỳ chung toàn quốc. Mỗi đề 45 trắc nghiệm + 9 đúng/sai; xem phạm vi bài trên từng thẻ.':tab==='mocks'?'Định dạng chính thức: 24 TN + 6 nhóm Đ/S in trên đề; thí sinh ICT làm 2 nhóm chung + 2 nhóm ICT (tổng 4), không làm phần CS. Ba bộ ở đây chỉ chứa 24 TN + 4 nhóm cần làm, có kiến thức lớp 10–11. Thời gian thi chính thức: <strong>50 phút</strong>; chế độ luyện giữ <strong>40 giây/câu hoặc ý</strong> (tối đa 26 phút 40 giây). Tỉ lệ mức độ 40/30/30 là ma trận biên soạn đề xuất, không phải quy định cố định đã xác minh của Bộ.':tab==='combined'?'Đề kết hợp chủ đề: 45 câu trắc nghiệm + 9 câu đúng/sai. Mỗi ý đúng/sai có 40 giây riêng.':'7 đề chủ đề A–G: mỗi đề 18 câu trắc nghiệm + 2 câu đúng/sai.';html+=`<div class="notice">${notice}</div><div class="grid">${selectedExams.map(card).join('')}</div>`}content.innerHTML=html;document.querySelectorAll('[data-exam]').forEach(b=>b.onclick=()=>{const assigned=dashboard.assignments.some(a=>a.examId===b.dataset.exam);if(assigned){tab='assignments';renderStudent();toast('Đề này có lịch giao cho lớp. Hãy chọn bài được giao.')}else confirmExam(b.dataset.exam)});if(ongoing)$('#resume').onclick=()=>confirmExam(ongoing.examId,ongoing.id)}else if(tab==='history'){content.innerHTML=historyTable(dashboard.attempts);bindReviews()}else if(tab==='analysis'){content.innerHTML='<p class="loading">Đang phân tích kết quả…</p>';const x=await api('analysis');if(renderId!==studentRender)return;content.innerHTML=(x.reviewBlocked?'<div class="notice">Lời giải tạm ẩn vì bạn còn bài đang làm. Hoàn tất bài rồi quay lại ôn tập.</div>':'')+'<div class="practice-callout"><div><h2>Biến lỗi sai thành điểm mạnh.</h2><p>Luyện lại tối đa 15 trắc nghiệm + 2 nhóm đúng/sai từ lịch sử của bạn.</p></div><button class="primary" id="practice-wrong">Luyện câu sai →</button></div>'+analysisHTML(x.analysis);$('#practice-wrong').disabled=!!x.reviewBlocked;$('#practice-wrong').onclick=practiceWrong}else passwordHTML(content)}
function historyTable(rows,isAdmin=false){return rows.length?`<div class="table-wrap"><table><thead><tr>${isAdmin?'<th>Học sinh / lớp</th>':''}<th>Bộ đề</th><th>Thời gian bắt đầu</th><th>Điểm /10</th><th>Thời lượng</th><th>Vi phạm</th><th>Kết quả</th></tr></thead><tbody>${rows.map(a=>`<tr>${isAdmin?`<td><button class="link" data-student="${esc(a.userId)}">${esc(a.name)}</button><br><span class="small">${esc(a.className)}</span></td>`:''}<td>${esc(a.title||(isAdmin?admin.exams:dashboard.exams).find(e=>e.id===a.examId)?.title||a.examId)}</td><td>${date(a.startedAt)}</td><td><strong>${a.score==null?'—':a.score.toFixed(2)}</strong></td><td>${duration(a.duration)}</td><td>${a.violations||0}</td><td>${a.status==='active'?'<span class="status">Đang làm</span>':a.status==='closed'?(isAdmin?`<button class="ghost" data-review="${a.id}">Xem nháp · không nhận điểm</button>`:'<span class="status incorrect">Bài đã đóng — không nhận điểm</span>'):`<button class="ghost" data-review="${a.id}">Xem chi tiết</button>`}</td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">Chưa có bài làm. Kết quả sẽ xuất hiện tại đây sau khi bạn nộp bài.</div>'}
function bindReviews(){document.querySelectorAll('[data-review]').forEach(b=>b.onclick=async()=>{try{showResult(await api('review',{attemptId:b.dataset.review}))}catch(e){toast(e.message,true)}})}
function passwordHTML(el){el.innerHTML=`<form class="card password-form" id="password-form"><h2>Đổi mật khẩu</h2><div class="field"><label for="old-password">Mật khẩu hiện tại</label><input type="password" id="old-password" autocomplete="current-password" required></div><div class="field"><label for="new-password">Mật khẩu mới (từ 10 kí tự)</label><input type="password" id="new-password" autocomplete="new-password" required minlength="10" maxlength="128"></div><button class="primary">Cập nhật mật khẩu</button></form>`;$('#password-form').onsubmit=async e=>{e.preventDefault();try{await api('changePassword',{oldPassword:$('#old-password').value,password:$('#new-password').value});user=null;account();login();toast('Đã đổi mật khẩu. Hãy đăng nhập lại.')}catch(e){toast(e.message,true)}}}
function confirmExam(id,resumeId,assignmentId){const assignment=dashboard.assignments.find(a=>a.id===assignmentId),resume=dashboard.attempts.find(a=>a.id===resumeId),close=assignment?.closesAt||resume?.assignmentClose;const e=dashboard.exams.find(e=>e.id===id)||dashboard.attempts.find(a=>a.id===resumeId)?.practiceInfo;app.innerHTML=`<section class="layout" style="max-width:800px">${header(resumeId?'Tiếp tục bài làm':esc(e.title),'Làm bài nghiêm túc để kết quả phản ánh đúng năng lực của bạn.')}${examNotice(e)?`<div class="notice">${esc(examNotice(e))}</div>`:''}${close?`<div class="notice danger" id="deadline-policy"><strong>Hạn nhận bài: ${date(close)}</strong><br>Bạn phải gửi Nộp bài hoặc câu cuối đến máy chủ TRƯỚC hạn. Đồng hồ từng câu không gia hạn bài giao. Hết hạn mà chưa nộp hợp lệ: đóng bài, giữ đáp án đã gửi nhưng KHÔNG nhận điểm; không có thời gian ân hạn.</div>`:''}<div class="card"><ul class="rule-list"><li>${e.mcq} câu chọn một đáp án và ${e.tf} câu đúng/sai, mỗi câu có 4 ý.</li><li><strong>40 giây mỗi câu trắc nghiệm / mỗi ý đúng-sai.</strong> Hết giờ tự chuyển. Không quay lại câu trước.</li><li>Trắc nghiệm: 0,25 điểm/câu. Đúng-sai: đúng 1/2/3/4 ý được 0,1/0,25/0,5/1 điểm. Quy đổi tổng về thang 10.</li><li>Rời tab, mất tiêu điểm hoặc thoát toàn màn hình được ghi nhận. Tự nộp khi đủ ${e.maxViolations} lần vi phạm. Các sự kiện cùng một lần rời trang được gộp.</li><li>Chặn sao chép, bôi chọn, kéo thả, menu chuột phải và một số phím tắt. Tên người làm hiện trên watermark.</li><li>Mất mạng hay tải lại trang <strong>không dừng đồng hồ</strong>. Bài làm và đáp án đã gửi được lưu trên máy chủ.</li><li>Trình duyệt không thể chặn tuyệt đối ảnh chụp, thiết bị thứ hai hay công cụ can thiệp. Nhật kí cần được giáo viên xem xét, không phải kết luận tự động về ý định gian lận.</li></ul><div class="notice">Tên, lớp, đáp án, điểm và các sự kiện rời trang sẽ được lưu để giáo viên đánh giá. Không nhập thông tin nhạy cảm vào tài khoản.</div><p class="small">Nên sử dụng máy tính với trình duyệt hỗ trợ toàn màn hình. Trên điện thoại, khả năng kiểm soát toàn màn hình có thể hạn chế.</p><div class="question-bottom"><button class="ghost" id="cancel-exam">Quay lại</button><button class="primary" id="begin-exam">Tôi hiểu · ${resumeId?'Tiếp tục':'Vào bài làm'} ↗</button></div></div></section>`;$('#cancel-exam').onclick=renderStudent;$('#begin-exam').onclick=async()=>{const button=$('#begin-exam');button.disabled=true;try{if(document.documentElement.requestFullscreen)try{await document.documentElement.requestFullscreen()}catch{toast('Không mở được toàn màn hình. Các biện pháp khác vẫn hoạt động.')}const x=await api(resumeId?'current':'start',resumeId?{attemptId:resumeId}:{examId:id,assignmentId});if(x.closed)return handleClosed(x);if(x.result)return showResult(x);active=x.attempt;document.body.classList.add('taking');$('#logout').disabled=true;renderStep(x.step);if(resumeId)await violation('reload',true)}catch(error){toast(error.message,true);button.disabled=false}}}
function renderStep(s){if(!active)return;step=s;selected=null;clockOffset=Date.now()-s.serverNow;const e={title:active.title||dashboard.exams.find(e=>e.id===active.examId)?.title||'Luyện lại câu sai'};app.innerHTML=`<section id="exam"><div class="exam-top"><div><p class="eyebrow">${esc(e.title)}</p><h1 class="exam-title">${s.type==='mcq'?'Chọn một đáp án':'Đúng hay sai? · Ý '+s.label.toUpperCase()}</h1><p class="muted">${esc(user.name)} · ${esc(user.className||'Tin học 12')}</p></div><div class="clock" id="clock"><strong id="seconds">40</strong><span>GIÂY CÒN LẠI</span></div></div><div class="progress-track"><div id="progressBar" style="width:${s.index/s.total*100}%"></div></div><div class="exam-meta"><span>${esc(s.section||'')} · Lượt trả lời ${s.index+1}/${s.total} · Chủ đề ${s.topic} · Bài ${s.lesson}</span><span id="violations">Vi phạm: ${s.violations}/${s.maxViolations}</span></div>${active.assignmentClose?`<p class="deadline-strip">Hạn nhận bài: ${date(active.assignmentClose)} · Phải nộp trước hạn</p>`:''}<div id="exam-network" role="alert"></div><article class="card question-card" id="questionCard">${s.scenario?`<div class="scenario">${esc(s.scenario)}</div>`:''}<h2>${esc(s.question)}</h2><div class="options">${(s.options||['Đúng','Sai']).map((o,i)=>`<button class="option" data-choice="${i}"><span class="letter">${s.type==='mcq'?'ABCD'[i]:i===0?'Đ':'S'}</span><span>${esc(o)}</span></button>`).join('')}</div><div class="question-bottom"><button class="ghost" id="early-submit">Nộp bài sớm</button><button class="primary" id="next-answer" disabled>Xác nhận & tiếp tục →</button></div></article><p class="fine exam-note">Đã gửi sẽ không sửa được. Hết giờ sẽ tự động bỏ trống và chuyển tiếp.</p><button class="ghost" id="sync-exam">Lấy lại câu hiện tại / khôi phục kết nối</button></section><div class="watermark" aria-hidden="true">${Array(10).fill(`<span>${esc(user.name)} · ${esc(user.username)}</span>`).join('')}</div>`;window.scrollTo(0,0);document.querySelectorAll('[data-choice]').forEach(b=>b.onclick=()=>{selected=s.type==='mcq'?+b.dataset.choice:+b.dataset.choice===0;document.querySelectorAll('[data-choice]').forEach(x=>x.classList.toggle('selected',x===b));$('#next-answer').disabled=false});$('#next-answer').onclick=()=>answer(selected);$('#sync-exam').onclick=syncExam;$('#early-submit').onclick=async()=>{if(!confirm('Nộp bài ngay? Những câu chưa làm sẽ được tính chưa trả lời.'))return;try{showResult(await api('submit',{attemptId:active.id}))}catch(e){toast(e.message,true);if(e.status===403)await syncExam()}};clearInterval(timer);timer=setInterval(tick,200);tick();}
async function tick(){if(!active||!step)return;const remaining=Math.max(0,Math.ceil((step.deadline-(Date.now()-clockOffset))/1000));const el=$('#seconds');if(el)el.textContent=remaining;$('#clock')?.classList.toggle('urgent',remaining<=8);if(remaining===0&&!examBusy)await answer(null)}
async function answer(value){if(examBusy||!active)return;examBusy=true;const id=active.id,index=step.index;$('#questionCard')?.classList.add('busy');try{const x=await api('answer',{attemptId:id,index,value});if(x.closed)handleClosed(x);else if(x.result)showResult(x);else renderStep(x.step)}catch(e){toast(e.message,true);try{const x=await api('current',{attemptId:id});if(x.closed)handleClosed(x);else if(x.result)showResult(x);else renderStep(x.step)}catch{}}finally{examBusy=false;$('#questionCard')?.classList.remove('busy')}}
async function violation(kind,force=false){if(!active||!step)return;const now=Date.now();if(!force&&now-lastViolation<2000)return;lastViolation=now;document.body.classList.add('obscured');try{const x=await api('violation',{attemptId:active.id,kind,clientAt:new Date().toISOString()});if(x.closed){handleClosed(x);return}if(x.result){showResult(x);return}if(x.step.index!==step.index)renderStep(x.step);step.violations=x.step.violations;$('#violations').textContent=`Vi phạm: ${x.step.violations}/${x.step.maxViolations}`;guard(x.step)}catch(e){toast('Không gửi được nhật kí: '+e.message,true)}}
function guard(s){if(!active)return;guarding=true;$('#guard')?.remove();const el=document.createElement('div');el.id='guard';el.className='guard';el.innerHTML=`<div class="card"><div class="guard-icon">!</div><p class="eyebrow">NHẮC NHỞ LÀM BÀI</p><h2>Bài làm cần được tập trung.</h2><p>Đã ghi nhận ${s.violations}/${s.maxViolations} lần rời bài. Hệ thống sẽ tự nộp khi đạt ngưỡng. Đồng hồ vẫn chạy.</p><button class="primary" id="guard-back">Trở lại bài làm</button></div>`;document.body.append(el);$('#guard-back').onclick=async()=>{try{if(!document.fullscreenElement&&document.documentElement.requestFullscreen)await document.documentElement.requestFullscreen()}catch{}el.remove();guarding=false;document.body.classList.remove('obscured')};}
function endExam(){active=null;step=null;selected=null;clearInterval(timer);timer=null;guarding=false;$('#guard')?.remove();document.body.classList.remove('taking','obscured');$('#logout')?.removeAttribute('disabled');if(document.fullscreenElement)document.exitFullscreen().catch(()=>{})}
function displayValue(q,v){if(v===null||v===undefined)return'Chưa trả lời';return q.type==='tf'?(v?'Đúng':'Sai'):q.options?.[v]||'—'}
function wrongHTML(q){return`<details class="review-item"><summary><span>Chủ đề ${q.topic} · Bài ${q.lesson} · ${q.level} — ${esc(q.question)}</span><span class="status ${q.correct?'correct':'incorrect'}">${q.correct?'Đúng':'Chưa đúng'}</span></summary><div class="review-body"><p class="answer-row">Bạn chọn: ${esc(displayValue(q,q.selected))}</p><p class="answer-row">Đáp án: ${esc(displayValue(q,q.answer))}</p><p class="explain">${esc(q.explanation)}</p><p class="small"><strong>Cần xem lại:</strong> ${esc(q.review)}</p></div></details>`}
function showResult(x){if(x.closed)return handleClosed(x);endExam();const a=x.attempt,r=x.result;app.innerHTML=`<section id="results"><div class="result-heading"><p class="eyebrow">BÀI LÀM ĐÃ ĐƯỢC LƯU TRÊN MÁY CHỦ</p><h1>Một lần làm, một lần hiểu hơn.</h1><p class="muted">${esc(a.name)} · ${esc(a.className)} · ${date(a.finishedAt)}</p></div><div class="score-card"><div><p class="eyebrow">ĐIỂM QUY ĐỔI</p><p class="big-score"><strong>${r.score.toFixed(2)}</strong><span>/ 10</span></p></div><div class="score-details"><p>Điểm gốc: <strong>${r.raw} / ${r.max}</strong></p><p>Thời gian: ${duration(a.duration)}</p><p>Vi phạm: ${a.violations||0}</p><p>${esc(a.reason)}</p></div></div><button class="primary" id="back-home">← Về không gian học tập</button><div class="review-heading"><h2>Nhìn lại để tiến bộ</h2><p>Giải thích và vị trí cần xem lại trong sách giáo khoa.</p></div>${r.answersHidden?`<div class="notice answers-hidden">${esc(r.answersHiddenReason||'Lời giải đang tạm ẩn theo thiết lập giáo viên.')} Bạn vẫn xem được điểm.</div>`:`<div class="review-tools"><label><input type="checkbox" id="wrong-only" checked> Chỉ xem câu sai (${r.answers.filter(q=>!q.correct).length})</label></div><div id="review-list">${r.answers.filter(q=>!q.correct).map(wrongHTML).join('')||'<div class="empty">Bạn đã trả lời đúng tất cả các câu. Rất tốt!</div>'}</div>`}</section>`;if($('#wrong-only'))$('#wrong-only').onchange=()=>{$('#review-list').innerHTML=r.answers.filter(q=>!$('#wrong-only').checked||!q.correct).map(wrongHTML).join('')||'<div class="empty">Không có câu sai.</div>'};$('#back-home').onclick=async()=>{try{await home()}catch(e){toast(e.message,true)}};window.scrollTo(0,0)}
function analysisHTML(a){const bars=(group,type)=>Object.entries(group).map(([id,s])=>{let title=type==='lesson'?'Bài '+id+' · '+(lessons.find(l=>l.id===+id)?.title||''):type==='topic'?'Chủ đề '+id:({NB:'Nhận biết',TH:'Thông hiểu',VD:'Vận dụng'}[id]||id);return`<div class="bar-row"><div class="bar-label"><span>${esc(title)}</span><strong>${s.accuracy}% · ${s.correct}/${s.total}</strong></div><div class="bar ${s.accuracy<60?'weak':''}"><i style="width:${s.accuracy}%"></i></div></div>`}).join('')||'<p class="small">Chưa có dữ liệu.</p>';const total=Object.values(a.stats.topic).reduce((n,s)=>n+s.total,0);if(!total)return'<div class="empty">Chưa đủ dữ liệu đánh giá. Hãy hoàn thành ít nhất một bộ đề.</div>';return`<div class="notice">Tỉ lệ đúng được tính trên từng lượt chọn và từng ý đúng/sai, kể cả câu bỏ trống. Dưới 60%: cần ôn lại · 60–79%: cần củng cố · từ 80%: nắm vững. Đây là gợi ý học tập, không phải kết luận toàn diện về năng lực.</div><div class="analysis-grid"><div class="card"><h3>Theo chủ đề</h3>${bars(a.stats.topic,'topic')}</div><div class="card"><h3>Theo mức độ</h3>${bars(a.stats.level,'level')}</div><div class="card" style="grid-column:1/-1"><h3>Theo bài học</h3>${bars(a.stats.lesson,'lesson')}</div></div><div class="section-head"><h2>Lộ trình cần ôn lại</h2></div>${a.recommendations.map(r=>`<article class="recommend"><h3>Bài ${r.lesson} · ${esc(r.title)} <span class="status ${r.accuracy>=80?'correct':'incorrect'}">${r.status} · ${r.accuracy}%</span></h3><p>${esc(r.text)}</p><p>${r.accuracy<80?'Đọc lại mục được chỉ ra → ghi 3 ý chính → làm lại đề bài học → đối chiếu lời giải sau nộp.':'Luyện thêm đề chủ đề và đề tổng hợp để tăng khả năng vận dụng.'}</p></article>`).join('')}<div class="section-head"><h2>Các câu cần xem lại</h2><p>Tối đa 200 lượt sai gần nhất</p></div>${a.wrong.length?a.wrong.map(wrongHTML).join(''):'<div class="empty">Chưa có câu sai được hiển thị.</div>'}`}
async function renderAdmin(){const renderId=++adminRender;if(['results','statistics','curriculum'].includes(tab))admin=await api('adminData');if(renderId!==adminRender)return;app.innerHTML=`<section class="layout">${header('Hiểu lớp học qua từng kết quả.','Cấp tài khoản, điều phối bài kiểm tra và phát hiện phần kiến thức cần ôn lại.')}${nav([['portal','★ Cổng giáo viên'],['students','Học sinh'],['classes','Lớp & bài giao'],['ranking','Bảng xếp hạng'],['exams','Bộ đề'],['import','Nhập câu hỏi'],['curriculum','Phân phối & phạm vi'],['results','Kết quả'],['statistics','Phân tích lớp'],['help','Hướng dẫn'],['password','Mật khẩu']])}<div id="admin-content"></div></section>`;bindTabs(renderAdmin);const c=$('#admin-content');if(tab==='portal'){PT.data=null;return renderPortal('overview')}if(tab==='help')return helpHTML(c);if(tab==='curriculum')return curriculumHTML(c);if(tab==='classes')return classesHTML(c);if(tab==='ranking')return rankingSettings(c);if(tab==='import')return importHTML(c);if(tab==='students')studentsHTML(c);else if(tab==='exams')examsHTML(c);else if(tab==='results')resultsHTML(c);else if(tab==='statistics'){c.innerHTML=filterHTML()+'<div id="stats-content"></div>';bindFilters(loadStats);await loadStats()}else passwordHTML(c)}
function studentsHTML(c){const students=admin.users.filter(u=>u.role==='student');c.innerHTML=`<div class="metric-grid"><div class="metric"><strong>${students.length}</strong><span>Tài khoản học sinh (kể cả TEST)</span></div><div class="metric"><strong>${new Set(students.map(s=>s.className).filter(Boolean)).size}</strong><span>Lớp đang theo dõi</span></div><div class="metric"><strong>${students.filter(s=>s.locked).length}</strong><span>Tài khoản đang khóa</span></div></div><details class="card" open><summary><strong>Cấp tài khoản học sinh</strong></summary><p class="small">Mỗi dòng: tên đăng nhập, mật khẩu, họ tên, lớp. Hỗ trợ CSV có dấu ngoặc kép hoặc phân cách bằng tab. Mật khẩu tối thiểu 8 kí tự. Không có tự đăng kí công khai.</p><form id="import-form"><label for="student-csv">Danh sách tài khoản (tối đa 200 dòng/lần)</label><textarea id="student-csv" rows="5" required placeholder="username,password,name,class&#10;hs12a01,MatKhauRieng01,Nguyễn Minh An,12A1"></textarea><div class="form-row" style="margin-top:15px"><button class="primary">Tạo các tài khoản</button></div><div id="import-result" class="import-result" role="status"></div></form></details><div class="section-head"><h2>Danh sách học sinh</h2><input id="student-search" aria-label="Tìm học sinh" placeholder="Tìm tên, lớp, tài khoản" style="max-width:280px"></div><div id="students-table"></div>`;const render=()=>{const term=$('#student-search').value.toLowerCase();$('#students-table').innerHTML=`<div class="table-wrap"><table><thead><tr><th>Tài khoản</th><th>Họ tên / lớp</th><th>Trạng thái</th><th>Đặt lại mật khẩu</th><th>Thao tác</th></tr></thead><tbody>${students.filter(s=>(s.name+' '+s.className+' '+s.username).toLowerCase().includes(term)).map(s=>`<tr><td>${esc(s.username)}</td><td>${esc(s.name)}<br><span class="small">${esc(s.className)}</span></td><td>${s.locked?'Đang khóa':'Hoạt động'}</td><td><input type="password" id="reset-${esc(s.id)}" placeholder="Mật khẩu mới" autocomplete="new-password" aria-label="Mật khẩu mới cho ${esc(s.name)}"><button class="ghost" data-reset="${esc(s.id)}">Đặt lại</button></td><td><button class="ghost" data-edit="${esc(s.id)}">Sửa</button> <button class="ghost" data-lock="${esc(s.id)}">${s.locked?'Mở khóa':'Khóa'}</button> <button class="ghost" data-student="${esc(s.id)}">Kết quả</button></td></tr>`).join('')}</tbody></table></div>`;document.querySelectorAll('[data-lock]').forEach(b=>b.onclick=async()=>{const s=students.find(s=>s.id===b.dataset.lock);try{await api('updateStudent',{id:s.id,locked:!s.locked});admin=await api('adminData');studentsHTML(c)}catch(e){toast(e.message,true)}});document.querySelectorAll('[data-reset]').forEach(b=>b.onclick=async()=>{const p=document.getElementById('reset-'+b.dataset.reset);try{if(p.value.length<8)throw Error('Mật khẩu mới cần ít nhất 8 kí tự.');await api('updateStudent',{id:b.dataset.reset,password:p.value});p.value='';toast('Đã đặt lại mật khẩu và vô hiệu các phiên cũ.')}catch(e){toast(e.message,true)}});document.querySelectorAll('[data-edit]').forEach(b=>b.onclick=()=>editStudent(students.find(s=>s.id===b.dataset.edit),c));bindStudentDrill()};$('#student-search').oninput=render;render();$('#import-form').onsubmit=async e=>{e.preventDefault();const text=$('#student-csv').value;try{const rows=parseCSV(text);const x=await api('createStudents',{rows});const result=x.results.map(r=>r.username+': '+(r.ok?'Đã tạo':r.error)).join('\n');admin=await api('adminData');studentsHTML(c);$('#import-result').textContent=result;toast('Đã xử lí danh sách tài khoản.')}catch(e){toast(e.message,true)}}}
function parseCSV(text){const delimiter=text.includes('\t')?'\t':',',rows=[];let row=[],field='',quoted=false;for(let i=0;i<text.length;i++){const ch=text[i];if(ch==='"'){if(quoted&&text[i+1]==='"'){field+='"';i++}else quoted=!quoted}else if(ch===delimiter&&!quoted){row.push(field.trim());field=''}else if((ch==='\n'||ch==='\r')&&!quoted){if(ch==='\r'&&text[i+1]==='\n')i++;row.push(field.trim());if(row.some(Boolean))rows.push(row);row=[];field=''}else field+=ch}row.push(field.trim());if(row.some(Boolean))rows.push(row);if(quoted)throw Error('CSV có dấu ngoặc kép chưa đóng.');return rows.filter((r,i)=>!(i===0&&['username','tên đăng nhập'].includes(r[0].toLowerCase()))).map(r=>({username:r[0],password:r[1],name:r[2],className:r[3]||''}))}
function examsHTML(c){c.innerHTML=`<div class="notice">Mỗi bài: 15 trắc nghiệm + 2 đúng/sai · Chủ đề: 18 + 2 · Đề kết hợp/học kỳ: 45 + 9 · Thi thử THPT: 24 + 4. Phân chia học kỳ là đề xuất, giáo viên cần xác nhận. THPT chính thức 50 phút; chế độ luyện tại đây 26 phút 40 giây. Đúng/sai luôn có 2 ý thông hiểu + 2 ý vận dụng. 40 giây/lượt trả lời. Đề kết hợp có thể dùng lại câu trong ngân hàng, không lặp câu trong cùng một đề.</div>${admin.exams.map(e=>`<details class="card" style="margin:14px 0;padding:20px"><summary><strong>${esc(e.title)}</strong> <span class="small">${e.mcq} TN / ${e.tf} Đ-S · ${e.open?'Đang mở':'Đang đóng'}</span></summary><form data-exam-settings="${e.id}" style="margin-top:20px"><div class="checks"><label><input name="open" type="checkbox" ${e.open?'checked':''}> Mở cho học sinh</label><label><input name="showAnswers" type="checkbox" ${e.showAnswers?'checked':''}> Hiện đáp án và giải thích sau nộp</label></div><div class="form-row"><div class="field"><label>Số lượt làm tối đa / học sinh<input name="attemptLimit" type="number" min="1" max="100" value="${e.attemptLimit}" required></label></div><div class="field"><label>Tự nộp sau số lần vi phạm<input name="maxViolations" type="number" min="1" max="20" value="${e.maxViolations}" required></label></div><button class="primary">Lưu thiết lập</button></div><p class="small">Ngưỡng vi phạm áp dụng cho bài bắt đầu sau khi lưu. Đóng đề không làm hủy các bài đã bắt đầu.</p></form></details>`).join('')}`;document.querySelectorAll('[data-exam-settings]').forEach(f=>f.onsubmit=async ev=>{ev.preventDefault();const d=new FormData(f);try{await api('updateExam',{id:f.dataset.examSettings,open:d.has('open'),showAnswers:d.has('showAnswers'),attemptLimit:+d.get('attemptLimit'),maxViolations:+d.get('maxViolations')});admin=await api('adminData');toast('Đã lưu cấu hình đề.')}catch(e){toast(e.message,true)}})}
let filters={examId:'',className:'',userId:''};
function filterHTML(){const classes=[...new Set(admin.users.filter(u=>u.role==='student').map(u=>u.className).filter(Boolean))];return`<p class="small">Mặc định loại dữ liệu TEST; lọc lớp hoặc tài khoản TEST để xem riêng. Thống kê gồm mọi bài đã nộp, cả luyện câu sai; bài đóng không nhận điểm.</p><div class="form-row"><div class="field"><label for="filter-exam">Bộ đề</label><select id="filter-exam"><option value="">Tất cả bộ đề</option>${admin.exams.map(e=>`<option value="${e.id}" ${filters.examId===e.id?'selected':''}>${esc(e.title)}</option>`).join('')}</select></div><div class="field"><label for="filter-class">Lớp</label><select id="filter-class"><option value="">Tất cả lớp</option>${classes.map(s=>`<option ${filters.className===s?'selected':''}>${esc(s)}</option>`).join('')}</select></div><div class="field"><label for="filter-user">Học sinh</label><select id="filter-user"><option value="">Tất cả học sinh</option>${admin.users.filter(u=>u.role==='student').map(s=>`<option value="${esc(s.id)}" ${filters.userId===s.id?'selected':''}>${esc(s.name)} (${esc(s.className)})</option>`).join('')}</select></div></div>`}
function bindFilters(fn){$('#filter-exam').onchange=()=>{filters.examId=$('#filter-exam').value;fn()};$('#filter-class').onchange=()=>{filters.className=$('#filter-class').value;fn()};$('#filter-user').onchange=()=>{filters.userId=$('#filter-user').value;fn()}}
function filteredAttempts(){const includeTests=/^TEST/i.test(filters.className)||/^test[_.-]/i.test(filters.userId);return admin.attempts.filter(a=>(includeTests||!(/^TEST/i.test(a.className||'')||/^test[_.-]/i.test(a.userId||'')))&&(!filters.examId||a.examId===filters.examId)&&(!filters.className||a.className===filters.className)&&(!filters.userId||a.userId===filters.userId))}
function resultsHTML(c){c.innerHTML=filterHTML()+'<div class="form-row"><label><input type="checkbox" id="export-detail"> Kèm chi tiết từng câu</label><button class="primary" id="export-xlsx">Xuất Excel .xlsx ↓</button><button class="ghost" id="export-csv">Xuất bảng điểm CSV ↓</button><button class="ghost" id="refresh-results">Làm mới</button></div><div id="results-table"></div>';const update=()=>{$('#results-table').innerHTML=historyTable(filteredAttempts(),true);bindReviews();bindStudentDrill()};bindFilters(update);update();$('#export-xlsx').onclick=exportXlsx;$('#export-csv').onclick=()=>exportCSV(filteredAttempts());$('#refresh-results').onclick=async()=>{try{admin=await api('adminData');if(!c.isConnected)return;update();toast('Đã cập nhật kết quả.')}catch(e){toast(e.message,true)}};}
function bindStudentDrill(){document.querySelectorAll('[data-student]').forEach(b=>b.onclick=async()=>{filters.userId=b.dataset.student;filters.className='';filters.examId='';tab='statistics';try{await renderAdmin()}catch(e){toast(e.message,true)}})}
async function loadStats(){const version=++statsRender,target=$('#stats-content');if(!target)return;target.innerHTML='<p class="loading">Đang phân tích dữ liệu…</p>';try{const x=await api('adminAnalysis',{...filters});if(version!==statsRender||!target.isConnected)return;target.innerHTML=chartsHTML(x.progress,false)+analysisHTML(x.analysis)+`<div class="section-head"><h2>Thống kê từng câu</h2></div><div class="card questions-stats" style="padding:0">${x.questionStats.length?x.questionStats.sort((a,b)=>a.accuracy-b.accuracy).map(q=>`<details><summary><strong>${q.accuracy}% đúng · ${q.correct}/${q.total}</strong> — ${esc(q.question)}</summary><p>Phương án sai được chọn nhiều nhất: ${q.mostWrong?esc(q.mostWrong[0])+' ('+q.mostWrong[1]+' lượt)':'Chưa có đáp án sai.'}</p></details>`).join(''):'<p class="empty">Chưa có dữ liệu câu hỏi.</p>'}</div><div class="section-head"><h2>Nhật kí vi phạm</h2><p>Các sự kiện cách nhau dưới 1,8 giây được gộp.</p></div><div class="table-wrap"><table><thead><tr><th>Học sinh</th><th>Thời gian máy chủ</th><th>Sự kiện</th><th>Lượt trả lời</th></tr></thead><tbody>${x.violations.map(v=>`<tr><td>${esc(admin.users.find(u=>u.id===v.userId)?.name||v.userId)}</td><td>${date(v.at)}</td><td>${esc({tab:'Đổi tab / ẩn trang',blur:'Mất tiêu điểm',fullscreen:'Thoát toàn màn hình',reload:'Tải lại / tiếp tục bài',shortcut:'Phím tắt bị hạn chế'}[v.kind]||v.kind)}</td><td>${v.questionIndex+1}</td></tr>`).join('')}</tbody></table></div>`}catch(e){if(target.isConnected&&version===statsRender)target.innerHTML=`<div class="notice danger">${esc(e.message)}</div>`}}
function exportCSV(rows){const cell=v=>{let s=String(v??'');if(/^[\s\x00-\x1f]*[=+@-]/.test(s))s="'"+s;return'"'+s.replaceAll('"','""')+'"'};const data=[['Tài khoản','Họ tên','Lớp','Đề','Điểm /10','Điểm gốc','Điểm tối đa','Bắt đầu (UTC+7)','Nộp bài (UTC+7)','Thời lượng giây','Vi phạm','Trạng thái','Lí do'],...rows.map(a=>[a.userId,a.name,a.className,a.title||admin.exams.find(e=>e.id===a.examId)?.title||a.examId,a.score,a.raw,a.max,date(a.startedAt),date(a.finishedAt),a.duration,a.violations,a.status,a.reason])];const url=URL.createObjectURL(new Blob(['\uFEFF'+data.map(r=>r.map(cell).join(',')).join('\r\n')],{type:'text/csv;charset=utf-8'}));const link=document.createElement('a');link.href=url;link.download='bang-diem-ict12.csv';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
// Deterrence controls, only while taking an exam; the server remains authoritative for time and grading.
document.addEventListener('visibilitychange',()=>{if(document.hidden&&active)violation('tab')});window.addEventListener('blur',()=>{if(active){document.body.classList.add('obscured');violation('blur')}});document.addEventListener('fullscreenchange',()=>{if(active&&!document.fullscreenElement)violation('fullscreen')});window.addEventListener('focus',()=>{if(!guarding)document.body.classList.remove('obscured')});for(const name of ['copy','cut','paste','contextmenu','dragstart','selectstart'])document.addEventListener(name,e=>{if(active)e.preventDefault()});document.addEventListener('keydown',e=>{if(!active)return;const k=e.key.toLowerCase(),blocked=e.key==='F12'||e.key==='PrintScreen'||((e.ctrlKey||e.metaKey)&&(['c','v','x','a','p','s','u'].includes(k)||(e.shiftKey&&['i','j','c','s'].includes(k))));if(blocked){e.preventDefault();toast('Thao tác này bị hạn chế trong khi làm bài.');if(e.key==='PrintScreen')violation('shortcut')}});window.addEventListener('beforeunload',e=>{if(active){e.preventDefault();e.returnValue=''}});
(async()=>{try{const x=await api('me');user=x.user;lessons=x.lessons;account();await home()}catch(e){if(e.status!==401)toast(e.message,true);login()}})();

function editStudent(student,target){const modal=document.createElement('div');modal.className='guard';modal.innerHTML=`<form class="card" style="text-align:left;width:100%" id="edit-student-form"><h2>Chỉnh sửa học sinh</h2><p class="small">${esc(student.username)}</p><div class="field"><label for="edit-name">Họ và tên</label><input id="edit-name" maxlength="100" required value="${esc(student.name)}"></div><div class="field"><label for="edit-class">Lớp</label><input id="edit-class" maxlength="50" value="${esc(student.className)}"></div><button class="primary">Lưu thông tin</button><button type="button" class="ghost" id="edit-cancel" style="margin-top:10px;width:100%">Hủy</button></form>`;document.body.append(modal);$('#edit-cancel').onclick=()=>modal.remove();$('#edit-student-form').onsubmit=async e=>{e.preventDefault();try{await api('updateStudent',{id:student.id,name:$('#edit-name').value,className:$('#edit-class').value});modal.remove();admin=await api('adminData');studentsHTML(target);toast('Đã cập nhật học sinh và kết thúc phiên đăng nhập cũ.')}catch(err){toast(err.message,true)}};}

function studentSummary(){const p=dashboard.progress;return`<div class="student-summary"><div class="summary-mark">12<span>ICT</span></div><div><p class="eyebrow">HÔM NAY BẠN SẼ TIẾN XA HƠN</p><h2>Chào ${esc(user.name.split(' ').at(-1))}, học một chút nhé.</h2><p>${p.count?p.count+' bài đã hoàn thành · Điểm trung bình '+p.average.toFixed(2)+'/10':'Bắt đầu từ một bài học. Mọi bước tiến đều được ghi nhận.'}</p></div><div class="summary-streak"><strong>${p.streak}</strong><span>ngày liên tiếp</span></div></div>`}
function chartsHTML(p,personal){const rows=p.timeline,limited=rows.slice(-30),points=limited.map((x,i)=>`${35+(i/(limited.length-1||1))*630},${175-x.score*15}`).join(' ');return`<div class="metric-grid"><div class="metric"><strong>${p.count}</strong><span>Bài hoàn thành</span></div><div class="metric"><strong>${p.average.toFixed(2)}</strong><span>Điểm trung bình /10</span></div><div class="metric"><strong>${personal?p.streak:p.topics.filter(t=>t.total&&t.accuracy<60).length}</strong><span>${personal?'Ngày luyện liên tiếp (UTC+7)':'Chủ đề cần ưu tiên ôn'}</span></div></div><div class="chart-grid"><article class="card"><div class="section-head"><h3>${personal?'Điểm qua từng lần luyện':'Điểm theo lượt làm'}</h3><span class="small">30 lượt gần nhất</span></div>${limited.length?`<svg class="score-chart" viewBox="0 0 700 210" role="img" aria-label="Biểu đồ điểm các bài đã nộp, thang 0 đến 10"><path d="M35 25H675 M35 100H675 M35 175H675" stroke="#e4eade" fill="none"/><text x="3" y="29">10</text><text x="11" y="104">5</text><text x="11" y="179">0</text><polyline points="${points}" fill="none" stroke="#35775e" stroke-width="3"/>${limited.map((x,i)=>`<circle cx="${35+i/(limited.length-1||1)*630}" cy="${175-x.score*15}" r="4" fill="#35775e"><title>${esc(date(x.at))}: ${x.score}/10</title></circle>`).join('')}</svg><details><summary class="small">Xem dữ liệu biểu đồ</summary><ol class="chart-values">${limited.map(x=>`<li>${date(x.at)} · ${esc(x.examId)}: <strong>${x.score}/10</strong></li>`).join('')}</ol></details>`:'<p class="empty">Nộp bài đầu tiên để bắt đầu biểu đồ.</p>'}</article><article class="card"><h3>Mức độ nắm vững A–G</h3><p class="small">Tỉ lệ đúng từng lượt trả lời, gồm cả bỏ trống.</p>${p.topics.map(t=>`<div class="bar-row"><div class="bar-label"><span title="${esc(topicName[t.id])}">Chủ đề ${t.id}</span><strong>${t.total?t.accuracy+'%':'Chưa học'}</strong></div><div class="bar ${t.accuracy<60?'weak':''}"><i style="width:${t.accuracy}%"></i></div></div>`).join('')}</article>${!personal?`<article class="card distribution"><h3>Phân bố điểm</h3><div class="distribution-bars">${p.distribution.map(d=>`<div><strong>${d.count}</strong><div class="dist-track"><i style="height:${d.count/Math.max(1,...p.distribution.map(d=>d.count))*110}px"></i></div><span>${d.label}</span></div>`).join('')}</div></article>`:''}</div>`}
function progressHTML(c,p,personal){c.innerHTML=chartsHTML(p,personal)+`<div class="section-head"><h2>Dấu mốc của bạn</h2><p>Ghi nhận sự cố gắng, không thay thế đánh giá của giáo viên.</p></div><div class="badges">${p.badges.map(b=>`<article class="badge ${b.earned?'earned':''}"><span class="badge-icon">${b.icon}</span><div><h3>${b.name}</h3><p>${b.text}</p><small>${b.earned?'Đã đạt':'Chưa đạt'}</small></div></article>`).join('')}</div>`}
function assignmentsHTML(c){const assignments=dashboard.assignments||[],now=Date.now()-dashboardClockOffset;c.innerHTML=`<div class="section-head"><h2>Bài dành cho lớp ${esc(user.className||'của bạn')}</h2><p>Tất cả thời gian hiển thị theo UTC+7.</p></div><div class="notice">Hạn đóng là hạn cuối nhận bài, kể cả khi bạn đang làm. Bài chưa nộp trước hạn sẽ đóng và không được nhận điểm. Đồng hồ 40 giây mỗi lượt vẫn áp dụng.</div><div class="grid">${assignments.map(a=>{const e=dashboard.exams.find(e=>e.id===a.examId),state=now<a.opensAt?'Chưa mở':now>=a.closesAt?'Đã hết hạn':'Đang nhận bài',ongoing=dashboard.attempts.find(x=>x.assignmentId===a.id&&x.status==='active');return`<article class="card assignment-card"><span class="topic-label">${state}</span><h3>${esc(e?.title||a.examId)}</h3><p class="small">Mở: ${date(a.opensAt)}<br><strong>Hạn nộp: ${date(a.closesAt)}</strong></p><button class="primary" data-assignment="${a.id}" ${now<a.opensAt||now>=a.closesAt?'disabled':''}>${ongoing?'Tiếp tục bài':'Vào bài được giao'} →</button></article>`}).join('')}</div>${!assignments.length?'<div class="empty">Chưa có bài giao cho lớp. Bạn vẫn có thể luyện theo bài học hoặc chủ đề.</div>':''}`;document.querySelectorAll('[data-assignment]').forEach(b=>b.onclick=()=>{const a=assignments.find(a=>a.id===b.dataset.assignment),ongoing=dashboard.attempts.find(x=>x.assignmentId===a.id&&x.status==='active');confirmExam(a.examId,ongoing?.id,a.id)})}
async function leaderboardHTML(c){c.innerHTML=`<div class="section-head"><h2>Cùng nhau tiến bộ</h2><p class="small">Mã của bạn: ${esc(user.rankAlias)}</p><div class="field"><label for="rank-exam">Phạm vi xếp hạng</label><select id="rank-exam"><option value="">Tổng thể</option>${(user.role==='admin'?admin:dashboard).exams.map(e=>`<option value="${e.id}">${esc(e.title)}</option>`).join('')}</select></div></div><div id="rank-body" class="card"></div>`;const load=async()=>{const el=$('#rank-body');try{const x=await api('leaderboard',{examId:$('#rank-exam').value});el.innerHTML=x.hidden&&user.role!=='admin'?'<div class="empty">Giáo viên đang ẩn bảng xếp hạng.</div>':`<p class="small">${esc(x.rule)} Học sinh chỉ thấy mã ẩn danh, không thấy họ tên, tài khoản hay lớp. Giáo viên xem danh tính để đối chiếu. BXH là động lực học, không phải xếp loại chính thức.</p>${x.rows.length?`<div class="table-wrap"><table><thead><tr><th>Hạng</th><th>Học sinh</th><th>Lớp</th><th>Điểm /10</th><th>Số đề</th></tr></thead><tbody>${x.rows.map(r=>`<tr><td><span class="rank-medal">${r.rank<=3?['①','②','③'][r.rank-1]:r.rank}</span></td><td>${esc(r.name)}</td><td>${esc(r.className)}</td><td><strong>${r.score.toFixed(2)}</strong></td><td>${r.exams}</td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">Chưa có bài làm đủ điều kiện xếp hạng.</div>'}`;}catch(e){el.textContent=e.message}};$('#rank-exam').onchange=load;await load()}
function rankingSettings(c){c.innerHTML=`<form class="card" id="rank-settings"><h2>Quyền riêng tư bảng xếp hạng</h2><p>Chỉ học sinh đã đăng nhập xem được. Mặc định ẩn; tài khoản TEST, đang khóa và bài luyện câu sai không tham gia.</p><label class="checks"><input type="checkbox" id="ranking-enabled" ${admin.preferences.leaderboard?'checked':''}> Cho học sinh xem bảng xếp hạng</label><button class="primary">Lưu hiển thị</button></form><div id="admin-ranking"></div>`;$('#rank-settings').onsubmit=async ev=>{ev.preventDefault();try{await api('savePreferences',{leaderboard:$('#ranking-enabled').checked});admin=await api('adminData');toast('Đã lưu quyền hiển thị.')}catch(e){toast(e.message,true)}};leaderboardHTML($('#admin-ranking'))}
function classOptions(){return admin.classes.filter(c=>!c.disabled).map(c=>`<option value="${c.id}">${esc(c.name)}</option>`).join('')}
function localInputISO(v){return v?new Date(v+':00+07:00').toISOString():''}
function classesHTML(c){c.innerHTML=`<div class="notice">Mỗi học sinh thuộc một lớp. Chọn học sinh và lớp để chuyển lớp mà không đổi tài khoản/mật khẩu. Lịch bài giao được chốt khi bắt đầu bài.</div><div class="class-grid"><form class="card" id="create-class"><p class="eyebrow">01 · TỔ CHỨC LỚP</p><h2>Tạo lớp học</h2><div class="field"><label for="class-name">Tên lớp</label><input id="class-name" required maxlength="50" placeholder="Ví dụ: 12A1"></div><button class="primary">Tạo lớp</button></form><form class="card" id="assign-students"><p class="eyebrow">02 · THÀNH VIÊN</p><h2>Xếp học sinh vào lớp</h2><div class="field"><label for="member-class">Lớp đích</label><select id="member-class" required><option value="">Chọn lớp</option>${classOptions()}</select></div><div class="field"><label for="member-users">Học sinh (có thể chọn nhiều)</label><select id="member-users" multiple size="5" required>${admin.users.filter(u=>u.role==='student').map(u=>`<option value="${esc(u.id)}">${esc(u.name)} · ${esc(u.className)} (${esc(u.id)})</option>`).join('')}</select></div><button class="primary">Xếp lớp</button></form><form class="card" id="create-assignment"><p class="eyebrow">03 · ĐIỀU PHỐI</p><h2>Giao bài có thời hạn</h2><div class="field"><label for="assign-class">Lớp nhận bài</label><select id="assign-class" required><option value="">Chọn lớp</option>${classOptions()}</select></div><div class="field"><label for="assign-exam">Bộ đề</label><select id="assign-exam">${admin.exams.map(e=>`<option value="${e.id}">${esc(e.title)}</option>`).join('')}</select></div><div class="field"><label for="assign-open">Giờ mở (UTC+7)</label><input id="assign-open" type="datetime-local" required></div><div class="field"><label for="assign-close">Hạn đóng (UTC+7)</label><input id="assign-close" type="datetime-local" required></div><button class="primary">Giao bài</button></form></div><div class="section-head"><h2>Các lớp học</h2></div><div class="class-chips">${admin.classes.map(c=>`<span class="pill">${esc(c.name)} · ${admin.users.filter(u=>u.role==='student'&&u.className===c.name).length} học sinh</span>`).join('')||'<p class="small">Chưa tạo lớp học chính thức. Lớp cũ của học sinh vẫn được giữ nguyên.</p>'}</div><div class="section-head"><h2>Lịch giao bài</h2></div><div class="table-wrap"><table><thead><tr><th>Lớp</th><th>Đề</th><th>Mở UTC+7</th><th>Hạn UTC+7</th><th>Trạng thái</th></tr></thead><tbody>${admin.assignments.map(a=>`<tr><td>${esc(a.className)}</td><td>${esc(admin.exams.find(e=>e.id===a.examId)?.title)}</td><td>${date(a.opensAt)}</td><td>${date(a.closesAt)}</td><td>${a.disabled?'Đã ngừng giao':`<button class="ghost" data-disable-assignment="${a.id}">Ngừng giao</button>`}</td></tr>`).join('')}</tbody></table></div>`;
const reload=async()=>{admin=await api('adminData');classesHTML(c)};$('#create-class').onsubmit=async ev=>{ev.preventDefault();try{await api('createClass',{name:$('#class-name').value});await reload();toast('Đã tạo lớp.')}catch(e){toast(e.message,true)}};$('#assign-students').onsubmit=async ev=>{ev.preventDefault();try{await api('assignStudents',{classId:$('#member-class').value,userIds:[...$('#member-users').selectedOptions].map(o=>o.value)});await reload();toast('Đã cập nhật lớp cho học sinh.')}catch(e){toast(e.message,true)}};$('#create-assignment').onsubmit=async ev=>{ev.preventDefault();try{await api('createAssignment',{classId:$('#assign-class').value,examId:$('#assign-exam').value,opensAt:localInputISO($('#assign-open').value),closesAt:localInputISO($('#assign-close').value)});await reload();toast('Đã giao bài cho lớp.')}catch(e){toast(e.message,true)}};document.querySelectorAll('[data-disable-assignment]').forEach(b=>b.onclick=async()=>{try{await api('disableAssignment',{id:b.dataset.disableAssignment});await reload()}catch(e){toast(e.message,true)}})}
async function exportXlsx(){const b=$('#export-xlsx');b.disabled=true;try{const x=await api('exportXlsx',{...filters,detail:$('#export-detail').checked}),bytes=Uint8Array.from(atob(x.base64),c=>c.charCodeAt(0)),url=URL.createObjectURL(new Blob([bytes],{type:'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'})),a=document.createElement('a');a.href=url;a.download=x.filename;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Đã xuất tệp Excel theo bộ lọc.')}catch(e){toast(e.message,true)}finally{b.disabled=false}}
async function practiceWrong(){const b=$('#practice-wrong');b.disabled=true;try{if(document.documentElement.requestFullscreen)try{await document.documentElement.requestFullscreen()}catch{}const x=await api('practiceWrong');active=x.attempt;document.body.classList.add('taking');$('#logout').disabled=true;renderStep(x.step)}catch(e){endExam();toast(e.message,true);b.disabled=false}}
async function handleClosed(x){endExam();if(user?.role==='admin'&&x.draft){app.innerHTML=`<section class="layout"><h1>Bản nháp — không nhận điểm</h1><div class="notice danger">${esc(x.draft.notice)}<br>${esc(x.attempt.reason)}</div><button class="primary" id="draft-back">Về quản lý</button>${x.draft.answers.map(wrongHTML).join('')}</section>`;$('#draft-back').onclick=home;return}toast(x.attempt?.reason||'Đã quá hạn nhận bài.',true);await home()}

async function syncExam(){if(!active||examBusy)return;examBusy=true;const id=active.id;try{const x=await api('current',{attemptId:id});if(x.closed)return handleClosed(x);if(x.result)return showResult(x);active=x.attempt;renderStep(x.step);toast('Đã lấy trạng thái mới nhất từ máy chủ.')}catch(e){toast(e.message,true)}finally{examBusy=false}}
window.addEventListener('offline',()=>{if(active){const el=$('#exam-network');if(el)el.textContent='Đang mất mạng. Đồng hồ không dừng; các đáp án CHƯA gửi chưa được lưu.'}});
window.addEventListener('online',()=>{if(active)toast('Đã có mạng. Bấm Lấy lại câu hiện tại để đồng bộ với máy chủ.');});
function curriculumHTML(c){const config=admin.curriculum,terms=['midterm-1','final-1','midterm-2','final-2'];c.innerHTML=`<h2>Phân phối học kỳ & phạm vi đề</h2><div class="notice"><strong>${esc(config.label)}</strong><p>SGK có 28 bài, 7 chủ đề số 1–7; A–G chỉ là nhãn của ứng dụng. Nhà trường chủ động lập kế hoạch theo điều kiện thực tế. Đổi nhãn học kỳ không tự đổi câu hỏi; phạm vi bài ở bốn đề học kỳ bên dưới mới quyết định ngân hàng câu cho lượt làm mới.</p><p>Đề cũ/kết quả cũ không bị chấm lại. Mặc định là gợi ý chia theo thứ tự bài, không phải lịch quốc gia bắt buộc. <a href="https://thuvienphapluat.vn/cong-van/Giao-duc/Cong-van-5512-BGDDT-GDTrH-2020-xay-dung-va-to-chuc-thuc-hien-ke-hoach-giao-duc-cua-nha-truong-462988.aspx" target="_blank" rel="noopener">Tham khảo CV 5512</a>.</p></div><form id="curriculum-form"><details class="card" open><summary><strong>1 · Học kỳ cho 28 bài học</strong></summary><div class="curriculum-lessons">${lessons.filter(l=>l.id<=28).map(l=>`<label>Bài ${l.id} · ${esc(l.title)}<select data-lesson-semester="${l.id}"><option value="1" ${config.lessonSemesters[l.id]==='1'?'selected':''}>Học kỳ 1</option><option value="2" ${config.lessonSemesters[l.id]==='2'?'selected':''}>Học kỳ 2</option></select></label>`).join('')}</div></details><details class="card"><summary><strong>2 · Tên hiển thị chủ đề (không thay nội dung SGK)</strong></summary><div class="curriculum-topics">${Object.entries(config.topicLabels).map(([id,name])=>`<label>Chủ đề ${id} / SGK ${'ABCDEFG'.indexOf(id)+1}<input data-topic-label="${id}" maxlength="150" required value="${esc(name)}"></label>`).join('')}</div></details><details class="card" open><summary><strong>3 · Phạm vi thật của đề học kỳ</strong></summary><p class="small">Mỗi đề giữ 45 TN (30 NB + 10 TH + 5 VD) + 9 nhóm Đ/S. Chọn đủ bài để có đủ ngân hàng; không tự sinh câu hoặc nới phạm vi ngoài lựa chọn. Giữ Ctrl/Cmd để chọn nhiều trên máy tính; điện thoại dùng bộ chọn nhiều của trình duyệt.</p><div class="curriculum-terms">${terms.map(id=>`<label>${esc(admin.exams.find(e=>e.id===id)?.title.split(' · ')[0])}<select data-term-scope="${id}" multiple size="8">${lessons.filter(l=>l.id<=28).map(l=>`<option value="${l.id}" ${config.termScopes[id].includes(l.id)?'selected':''}>Bài ${l.id} · ${esc(l.title)}</option>`).join('')}</select></label>`).join('')}</div></details><details class="card"><summary><strong>4 · Nhãn học kỳ của đề tổng hợp/chủ đề</strong></summary><div class="curriculum-lessons">${admin.exams.filter(e=>e.kind!=='lesson').map(e=>`<label>${esc(e.title)}<select data-exam-semester="${e.id}">${[['all','Cả năm / chưa phân kỳ'],['1','Học kỳ 1'],['2','Học kỳ 2']].map(([v,t])=>`<option value="${v}" ${config.examSemesters[e.id]===v?'selected':''}>${t}</option>`).join('')}</select></label>`).join('')}</div></details><div class="form-row"><button class="primary" id="save-curriculum">Lưu kế hoạch & kiểm tra phạm vi</button><button type="button" class="ghost" id="download-curriculum">Tải cấu hình JSON</button><button type="button" class="ghost" id="reset-curriculum">Về gợi ý mặc định</button></div><p id="curriculum-status" role="status"></p></form>`;
$('#curriculum-form').onsubmit=async ev=>{ev.preventDefault();const b=$('#save-curriculum');b.disabled=true;try{const data=structuredClone(config);document.querySelectorAll('[data-lesson-semester]').forEach(el=>data.lessonSemesters[el.dataset.lessonSemester]=el.value);document.querySelectorAll('[data-topic-label]').forEach(el=>data.topicLabels[el.dataset.topicLabel]=el.value);document.querySelectorAll('[data-exam-semester]').forEach(el=>data.examSemesters[el.dataset.examSemester]=el.value);document.querySelectorAll('[data-term-scope]').forEach(el=>data.termScopes[el.dataset.termScope]=[...el.selectedOptions].map(o=>+o.value));const x=await api('saveCurriculum',{curriculum:data});admin.curriculum=x.curriculum;$('#curriculum-status').textContent='Đã lưu. Phạm vi áp dụng cho lượt bắt đầu sau khi lưu; dữ liệu cũ giữ nguyên.';toast('Đã lưu kế hoạch giáo viên.')}catch(e){$('#curriculum-status').textContent=e.message;toast(e.message,true)}finally{b.disabled=false}};
$('#download-curriculum').onclick=()=>{const u=URL.createObjectURL(new Blob([JSON.stringify(admin.curriculum,null,2)],{type:'application/json'})),a=document.createElement('a');a.href=u;a.download='ke-hoach-ict12.json';a.click();setTimeout(()=>URL.revokeObjectURL(u),1000)};
$('#reset-curriculum').onclick=async()=>{if(!confirm('Khôi phục gợi ý mặc định? Không xóa bài làm/kết quả cũ.'))return;try{await api('resetCurriculum');admin=await api('adminData');curriculumHTML(c)}catch(e){toast(e.message,true)}};}
function helpHTML(c){c.innerHTML=`<article class="card help"><p class="eyebrow">HƯỚNG DẪN SỬ DỤNG · ICT12</p><h2>Luyện đúng cách, quản lý minh bạch.</h2><details open><summary>Học sinh: bắt đầu, nộp và khôi phục</summary><ol><li>Dùng tài khoản giáo viên cấp. Kiểm tra tên/lớp trước khi làm. Chọn Bài được giao nếu đề có lịch lớp; các đề khác dùng để luyện.</li><li>Đọc kỹ hạn nhận bài (UTC+7). Phải gửi Nộp bài hoặc câu cuối đến máy chủ <strong>trước hạn</strong>; hạn đóng không cộng thêm 40 giây. Nếu chưa nộp hợp lệ khi đóng: không nhận điểm, chỉ giữ đáp án đã gửi để giáo viên xem bản nháp. Không có ân hạn vì mất mạng.</li><li>Mỗi TN và mỗi ý Đ/S có 40 giây, không quay lại. Hết giờ câu bỏ trống; hết toàn bài luyện tự chấm khi có request tiếp theo. Bài giao vẫn tuân thủ hạn đóng riêng.</li><li>Mất mạng không dừng đồng hồ. Đáp án đã gửi được giữ; lựa chọn chưa xác nhận có thể mất. Khi có mạng, bấm Lấy lại câu hiện tại. Tải lại/tiếp tục sẽ được ghi nhận là sự kiện rời bài. Phiên hết hạn: đăng nhập lại rồi tiếp tục nếu còn giờ.</li><li>Sau nộp xem câu sai/lời giải nếu giáo viên cho phép. Lời giải tạm ẩn khi bạn còn một bài đang làm. Luyện câu sai dùng lịch sử của chính bạn; câu đã sửa đúng sẽ ra khỏi nhóm sai gần nhất.</li></ol></details><details ${user.role==='admin'?'open':''}><summary>Giáo viên: chuẩn bị một đợt kiểm tra</summary><ol><li>Tạo lớp, cấp tài khoản bằng CSV hoặc xếp các tài khoản cũ vào lớp. Mỗi học sinh một lớp; chuyển lớp sẽ đóng bài giao cũ chưa hoàn tất, không xóa câu đã gửi.</li><li>Vào Phân phối & phạm vi để chỉnh kế hoạch trường: học kỳ từng bài, tên hiển thị chủ đề, phạm vi bốn đề học kỳ và nhãn học kỳ các đề. Mặc định chỉ là khuyến nghị; cần đủ 45 TN + 9 nhóm Đ/S. Thay phạm vi chỉ tác động lượt làm mới.</li><li>Thiết lập Bộ đề: mở/đóng, số lượt và ẩn/hiện lời giải. Giới hạn lượt tính theo mã đề, không tự đặt lại khi giao đợt mới; tăng số lượt nếu cần. Nếu dùng kiểm tra có tính điểm, cân nhắc ẩn lời giải đến khi cả lớp xong. Nội dung có thể được dùng lại giữa đề; người đã xem đáp án có thể nhớ được, không có biện pháp kỹ thuật xóa kiến thức đã biết.</li><li>Giao đề với giờ mở/hạn đóng UTC+7. Đóng bộ đề chặn lượt mới của bộ đề. Ngừng giao chặn lượt mới theo bài giao đó; nếu bộ đề vẫn mở, học sinh được luyện tự do trở lại. Bài đang làm vẫn giữ lịch đã chốt. Khi sửa lịch, tạo bài giao mới; bài cũ giữ hạn đã thông báo. Không bắt đầu trước mở hoặc sau đóng. Nộp phải đến máy chủ trước đóng.</li><li>Kết quả lọc theo lớp tại thời điểm bắt đầu bài (chuyển lớp không sửa lịch sử). Bài quá hạn không có điểm hợp lệ; Xem nháp chỉ phục vụ đối chiếu. Xuất Excel có tùy chọn từng câu; CSV có bảo vệ công thức nhưng nên ưu tiên .xlsx.</li><li>BXH mặc định ẩn, chỉ người đăng nhập xem, học sinh thấy mã ẩn danh. Không dùng BXH hay tín hiệu rời tab làm kết luận kỷ luật tự động. Mặc định thống kê/xuất điểm loại dữ liệu TEST; lọc lớp/tài khoản TEST để kiểm tra riêng. Các lượt luyện câu sai vẫn tính trong thống kê học tập, không phải điểm thi chính thức.</li><li>Giữ bí mật mật khẩu, hạn chế người dùng chung máy, đăng xuất sau sử dụng. Không có tự đăng ký công khai. Khóa/reset mật khẩu sẽ vô hiệu phiên. Dữ liệu có trên máy chủ; có thể xuất bảng điểm, cấu hình để lưu hồ sơ của trường. Excel không phải bản sao lưu đầy đủ. Quản trị triển khai có công cụ sao lưu riêng; khôi phục DB cần thao tác bảo trì, không xóa dữ liệu để “thử lại”.</li></ol></details><details open><summary>Chấm điểm & khác biệt với thi tốt nghiệp chính thức</summary><p>Theo QĐ 764/QĐ-BGDĐT (08/03/2024), môn Tin học chính thức 50 phút. Phần I: 24 câu chọn một đáp án (0,25/câu = 6 điểm). Phần II in 6 nhóm Đ/S: 2 chung + 2 CS + 2 ICT; thí sinh ICT làm 2 chung + 2 ICT, tổng 4 nhóm = 4 điểm, không làm cả hai định hướng.</p><p>Đúng 0/1/2/3/4 ý trong một nhóm được 0/0,1/0,25/0,5/1 điểm. Không có quy định mỗi nhóm phải có đúng 2 ý đúng và 2 ý sai. 3 bộ luyện ICT trên đây chứa đúng phần cần làm: 24 TN + 4 nhóm Đ/S; điểm tối đa gốc 10. Những đề bài/chủ đề/học kỳ khác có số câu riêng, tính điểm gốc rồi quy đổi /10.</p><p><strong>Đây là chế độ luyện 40 giây mỗi lượt, tuần tự, tối đa 26 phút 40 giây với bộ THPT; không phải mô phỏng đồng hồ/điều hướng 50 phút của kỳ thi thật.</strong> Ma trận mức độ là lựa chọn biên soạn, không phải tỷ lệ quốc gia cố định.</p></details><details open><summary>Nội dung, quyền riêng tư và giới hạn cần biết</summary><p>Đủ 28 bài SGK Tin học 12 Kết nối tri thức, định hướng ICT. A–G là nhãn ứng dụng cho Chủ đề 1–7; Bài 1–21 là lõi chung, Bài 22–28 thuộc ICT theo lời nói đầu SGK. Đề THPT có thêm kiến thức tiền đề 10–11.</p><p>Đã rà soát ngữ nghĩa nội bộ toàn ngân hàng 468 TN + 73 nhóm Đ/S (292 ý), gồm đáp án, lời giải và khả năng hiểu nhiều cách; có hồ sơ đối chiếu từng câu. Đã làm rõ các điểm mạng/CSS/HTML dễ hiểu sai và loại quy luật mọi nhóm đều 2 đúng–2 sai. Đây không phải chứng nhận chuyên gia độc lập hay đề Bộ GDĐT; giáo viên cần duyệt đề trước kiểm tra có tính điểm. Nhãn NB/TH/VD là phân loại biên soạn, nhiều câu phục vụ ôn cơ bản, chưa hiệu chỉnh độ khó bằng dữ liệu thực nghiệm. Tên nút Google Sites/Forms và Windows theo phiên bản SGK có thể khác thực tế; Forms hiện hành còn cần xuất bản riêng và cấp quyền phản hồi, không chỉ xuất bản Sites.</p><p>Hệ thống lưu tài khoản, tên, lớp, câu trả lời, điểm và sự kiện rời trang để theo dõi học tập. Chỉ giáo viên xem toàn lớp, học sinh xem kết quả của mình. Không nhập thông tin nhạy cảm không cần thiết. Chống gian lận chỉ phát hiện/hạn chế trên trình duyệt; không thể chặn tuyệt đối ảnh chụp, AI, extension hay thiết bị khác. Không xin quyền camera/micro/định vị.</p></details><h3>Nguồn đối chiếu</h3><ul><li><a href="https://xaydungchinhsach.chinhphu.vn/thi-tot-nghiep-thpt-2026-de-thi-mon-tin-hoc-goi-y-dap-an-119260612145639712.htm" target="_blank" rel="noopener">Cổng Chính phủ: đề/đáp án và cấu trúc Tin học 2026</a></li><li><a href="https://thuvienphapluat.vn/van-ban/Giao-duc/Quyet-dinh-764-QD-BGDDT-2024-cau-truc-dinh-dang-de-thi-Ky-thi-tot-nghiep-trung-hoc-pho-thong-601389.aspx" target="_blank" rel="noopener">QĐ 764/2024 — bản tra cứu văn bản Bộ GDĐT</a></li><li><a href="https://vqa.moet.gov.vn/vi/news/thong-bao/cau-truc-dinh-dang-de-thi-tot-nghiep-thpt-tu-nam-2025-74.html" target="_blank" rel="noopener">Cục QLCL: định dạng thi từ 2025</a></li><li><a href="https://thuvienphapluat.vn/cong-van/Giao-duc/Cong-van-5512-BGDDT-GDTrH-2020-xay-dung-va-to-chuc-thuc-hien-ke-hoach-giao-duc-cua-nha-truong-462988.aspx" target="_blank" rel="noopener">CV 5512 — quyền chủ động lập kế hoạch trường</a></li></ul><p class="small">Đối chiếu ngày 09/11/2026 (UTC+7). Không tự khẳng định tài liệu cũ áp dụng cho mọi kỳ thi tương lai; giáo viên đối chiếu thông báo năm thi.</p></article>`}
